/bin/bash -lc "PYTHONDONTWRITEBYTECODE=1 PYTHONPATH=.:tools/rlflow:isaaclab-training CUDA_VISIBLE_DEVICES= /home/mint/rl_dev/instinctRL_orchestrator/.venv/bin/python -B - <<'PY'
import json,hashlib,os
from pathlib import Path
from tools.reconcile_r6_capacity import reconcile
from tools.r6_budget import totals,admissible
from tools.r6_check_prepared_storage import inspect
from tools.r6_recovery import Journal
base=Path('docs/experiments/r6-robustness-auto'); freeze=base/'freeze-candidate-01'
load=lambda p:json.loads(p.read_text())
files=['package','protocol','split','capacity','disk','storage']
checked=[]
def pins(x):
 if isinstance(x,dict):
  if isinstance(x.get('path'),str) and isinstance(x.get('sha256'),str):
   p=Path(x['path']);actual=hashlib.sha256(p.read_bytes()).hexdigest();assert actual==x['sha256'],(str(p),actual,x['sha256']);checked.append(str(p))
  for v in x.values():pins(v)
 elif isinstance(x,list):
  for v in x:pins(v)
for n in files:pins(load(freeze/(n+'.json')))
print('direct_package_pins_verified',len(checked))
for new,old in [('protocol','TEST_PROTOCOL'),('split','SPLIT_MANIFEST')]:
 a=load(freeze/(new+'.json'));b=load(base/(old+'.json'))
 print('changed_fields',new)
 for k in a.keys()|b.keys():
  if a.get(k)"'!=b.get(k):print(k, json.dumps({'"'old':b.get(k),'new':a.get(k)})[:2400])
s=load(freeze/'budget-input-state.json');d=load(base/'CAPACITY_DUAL_VOLUME_DRAFT.json');r=load(base/'production-storage-baseline-01/REGISTRATION.json')
x=reconcile(s,d,r['event_key']);y=load(freeze/'disk.json');assert all(y[k]==v for k,v in x.items());print('disk_reconciliation_exact',x['development_headroom_bytes'],x['proposed_final_protection_bytes']-x['final_projected_bytes'])
current=load(base/'batch/state.json');print('current_ledger',totals(current['budget']));print('current_capacity',current['budget']['capacity_pass']);print('budget_snapshot',totals(s['budget']))
c=load(freeze/'capacity.json');assert sum(j['total_reserved_seconds'] for j in c['job_time_bounds'])==37190
